<template>
  <div class="comment-thread">
    <div v-for="item in timeline" :key="item.key">
      <!-- Agent Run -->
      <AgentRunCard
        v-if="item.type === 'run'"
        :run="item.run!"
        @stop="$emit('stop-run', $event)"
      />

      <!-- Comment -->
      <div v-else class="comment-item">
        <q-avatar
          size="28px"
          :icon="item.comment!.author_type === 'agent' ? 'smart_toy' : 'person'"
          :class="item.comment!.author_type === 'agent' ? 'comment-avatar--agent' : 'comment-avatar--human'"
        />
        <div class="comment-body">
          <div class="comment-meta">
            <strong>{{ item.comment!.author_name }}</strong>
            <q-badge
              v-if="item.comment!.run_id"
              color="dark"
              :label="$t('docnet_run_label') + ' ' + item.comment!.run_id.slice(0, 8)"
              class="run-ref-badge"
            />
            <span class="text-caption text-grey-6">{{ formatDate(item.comment!.created_on) }}</span>
          </div>
          <div
            v-if="item.comment!.author_type === 'agent'"
            class="comment-content markdown-body"
            v-html="renderMarkdown(item.comment!.content)"
          />
          <p v-else class="comment-content">{{ item.comment!.content }}</p>
        </div>
      </div>
    </div>

    <p v-if="timeline.length === 0" class="text-grey-6 text-caption q-pa-sm">
      {{ $t('no_comments_yet') }}
    </p>

    <!-- Add comment (human-assigned issues only) -->
    <div v-if="!readOnly && humanAssigned" class="add-comment">
      <q-input
        v-model="newComment"
        outlined
        dense
        :placeholder="$t('add_a_comment')"
        type="textarea"
        :rows="2"
        class="add-comment__input"
      />
      <div class="add-comment__actions">
        <q-space />
        <q-btn
          unelevated
          no-caps
          icon="cancel"
          :label="$t('docnet_comment_not_resolved')"
          :color="resolution === 'not_done' ? 'negative' : 'grey-3'"
          :text-color="resolution === 'not_done' ? 'white' : 'grey-8'"
          class="resolution-btn"
          @click="resolution = resolution === 'not_done' ? null : 'not_done'"
        />
        <q-btn
          unelevated
          no-caps
          icon="check_circle"
          :label="$t('docnet_resolved')"
          :color="resolution === 'done' ? 'positive' : 'grey-3'"
          :text-color="resolution === 'done' ? 'white' : 'grey-8'"
          class="resolution-btn"
          @click="resolution = resolution === 'done' ? null : 'done'"
        />
        <f-btn
          appearance="primary"
          :label="$t('comment')"
          icon="send"
          :disabled="!newComment.trim() || !resolution"
          class="comment-btn"
          @click="submitComment"
        />
      </div>
    </div>
  </div>
</template>

<script lang="ts">
import { notify } from 'src/components/notifications/notify';
import { defineComponent, type PropType } from 'vue';
import type { DocNetComment, DocNetAgentRun } from 'src/@types/docnet';
import AgentRunCard from './AgentRunCard.vue';
import { renderMarkdown } from 'src/utils/markdown';
import { formatRelativeTime } from 'src/utils/docnet/formatting';

export interface TimelineItem {
  key: string;
  type: 'comment' | 'run';
  timestamp: string;
  comment?: DocNetComment;
  run?: DocNetAgentRun;
}

export default defineComponent({
  name: 'CommentThread',

  components: {
    AgentRunCard,
  },

  props: {
    comments: {
      type: Array as PropType<DocNetComment[]>,
      required: true,
    },
    runs: {
      type: Array as PropType<DocNetAgentRun[]>,
      default: () => [],
    },
    readOnly: {
      type: Boolean,
      default: false,
    },
    humanAssigned: {
      type: Boolean,
      default: false,
    },
  },

  emits: ['add-comment', 'stop-run'],

  data() {
    return {
      newComment: '',
      resolution: null as 'done' | 'not_done' | null,
    };
  },

  computed: {
    timeline(): TimelineItem[] {
      const items: TimelineItem[] = [];

      // Collect run result texts to deduplicate agent comments that repeat a run's output
      const runResultTexts = new Set(
        this.runs
          .filter((r) => r.result_text)
          .map((r) => (r.result_text || '').trim()),
      );

      for (const comment of this.comments) {
        // Skip agent comments whose content matches a run's result_text
        if (
          comment.author_type === 'agent' &&
          comment.content &&
          runResultTexts.has(comment.content.trim())
        ) continue;
        items.push({
          key: 'comment-' + comment.id,
          type: 'comment',
          timestamp: comment.created_on,
          comment,
        });
      }

      for (const run of this.runs) {
        items.push({
          key: 'run-' + run.id,
          type: 'run',
          timestamp: run.started_at || run.created_on || new Date(0).toISOString(),
          run,
        });
      }

      return items.sort(
        (a, b) => new Date(a.timestamp).getTime() - new Date(b.timestamp).getTime(),
      );
    },
  },

  methods: {
    renderMarkdown,

    formatDate(isoString: string): string {
      const fallback = (d: string) => {
        const date = new Date(d);
        const now = new Date();
        return date.toLocaleDateString(undefined, {
          month: 'short',
          day: 'numeric',
          year: date.getFullYear() !== now.getFullYear() ? 'numeric' : undefined,
        });
      };
      return formatRelativeTime(isoString, this.$t, fallback);
    },

    submitComment(): void {
      const content = this.newComment.trim();
      if (!content || !this.resolution) return;

      const message = this.resolution === 'done'
        ? this.$t('docnet_issue_resolved_success')
        : this.$t('docnet_comment_sent_open');

      this.$emit('add-comment', { content, resolution: this.resolution });
      this.newComment = '';
      this.resolution = null;

      notify.success(message);
    },
  },
});
</script>

