<template>
  <div class="docnet-issue-detail">
    <!-- Loading -->
    <div v-if="loading" class="text-center q-pa-xl">
      <q-spinner-dots color="primary" size="40px" />
    </div>

    <!-- Not found -->
    <div v-else-if="!issue" class="text-center q-pa-xl">
      <q-icon name="search_off" size="64px" color="grey-5" />
      <p class="q-mt-md text-grey-6">{{ $t('issue_not_found') }}</p>
      <f-btn appearance="flat" :label="$t('back_to_issues')" icon="arrow_back" @click="goBack()" />
    </div>

    <!-- Issue detail -->
    <div v-else>
      <!-- Header -->
      <div class="issue-header row items-center q-mb-md no-wrap">
        <f-btn appearance="flat" icon="arrow_back" dense class="q-mr-sm" @click="goBack()" />
        <h2 class="issue-header__title">{{ issue.title }}</h2>
        <StatusBadge :status="issue.status" size="md" class="q-ml-sm" />
        <q-space />
        <q-btn-dropdown
            flat
            dense
            round
            icon="more_vert"
            dropdown-icon="none"
            class="actions-menu-btn"
          >
            <q-list dense class="actions-menu-list">
              <q-item clickable v-close-popup dense @click="showEditDialog = true">
                <q-item-section>
                  <div class="row items-center no-wrap q-gutter-x-sm">
                    <q-icon name="edit" size="16px" />
                    <span>{{ $t('docnet_edit_issue') }}</span>
                  </div>
                </q-item-section>
              </q-item>
              <q-item clickable v-close-popup dense @click="confirmDelete" class="text-negative">
                <q-item-section>
                  <div class="row items-center no-wrap q-gutter-x-sm">
                    <q-icon name="delete" size="16px" />
                    <span>{{ $t('docnet_delete_issue') }}</span>
                  </div>
                </q-item-section>
              </q-item>
            </q-list>
          </q-btn-dropdown>
      </div>

      <!-- Description -->
      <q-card flat bordered class="detail-card q-mb-md">
        <q-card-section>
          <div class="detail-section-label">{{ $t('docnet_description') }}</div>
          <div class="detail-description markdown-body" v-html="renderMarkdown(issue.description || '---')" />

          <!-- Properties list -->
          <q-separator class="q-my-md" />
          <div class="properties-list">
            <!-- Parent-mission link sits at the TOP of the properties
                 list — it answers "where am I?" before any timing or
                 status detail.  Same idea Linear/GitHub use for the
                 project/repo breadcrumb: the parent record is the
                 anchor, the rest of the rows are details about THIS
                 issue. -->
            <div v-if="issue.mission_id" class="properties-list__item">
              <span class="properties-list__label"><q-icon name="rocket_launch" size="14px" class="q-mr-xs" />{{ $t('docnet_mission') }}</span>
              <q-btn
                outline
                dense
                no-caps
                color="primary"
                icon-right="arrow_forward"
                :label="issue.mission_name || $t('mission')"
                class="properties-list__mission-link"
                @click="$router.push(`/doc-net/missions/${issue.mission_id}`)"
              />
            </div>
            <div class="properties-list__item">
              <span class="properties-list__label"><q-icon name="timer" size="14px" class="q-mr-xs" />{{ $t('docnet_time') }}</span>
              <span class="text-caption">{{ issueWallClock ? formatDuration(issueWallClock) : '—' }}</span>
            </div>
            <div class="properties-list__item">
              <span class="properties-list__label"><q-icon name="token" size="14px" class="q-mr-xs" />{{ $t('docnet_tokens') }}</span>
              <span class="text-caption">{{ totalTokens ? formatTokens(totalTokens) : '—' }}</span>
            </div>
            <div class="properties-list__item">
              <span class="properties-list__label"><q-icon name="flag" size="14px" class="q-mr-xs" />{{ $t('priority') }}</span>
              <PriorityIcon :priority="issue.priority" show-label />
            </div>
            <div class="properties-list__item">
              <span class="properties-list__label"><q-icon name="person" size="14px" class="q-mr-xs" />{{ $t('assignee') }}</span>
              <AssigneeChip v-if="issue.assignee_name" :name="issue.assignee_name" :type="issue.assignee_type" size="sm" />
              <span v-else class="text-grey-6 text-caption">{{ $t('docnet_unassigned') }}</span>
            </div>
            <div class="properties-list__item">
              <span class="properties-list__label"><q-icon name="person_outline" size="14px" class="q-mr-xs" />{{ $t('docnet_reporter') }}</span>
              <span>{{ issue.reporter_name }}</span>
            </div>
            <div v-if="issue.tags && issue.tags.length > 0" class="properties-list__item">
              <span class="properties-list__label"><q-icon name="label" size="14px" class="q-mr-xs" />{{ $t('docnet_labels') }}</span>
              <div class="properties-list__tags">
                <q-chip v-for="tag in issue.tags" :key="tag" dense size="sm" color="primary" text-color="white">{{ tag }}</q-chip>
              </div>
            </div>
            <div class="properties-list__item">
              <span class="properties-list__label"><q-icon name="schedule" size="14px" class="q-mr-xs" />{{ $t('docnet_created') }}</span>
              <span class="text-caption">{{ formatDate(issue.created_on) }}</span>
            </div>
            <div v-if="issue.last_modified_on" class="properties-list__item">
              <span class="properties-list__label"><q-icon name="update" size="14px" class="q-mr-xs" />{{ $t('docnet_updated') }}</span>
              <span class="text-caption">{{ formatDate(issue.last_modified_on) }}</span>
            </div>
          </div>
        </q-card-section>
      </q-card>

      <!-- Tabbed section -->
      <q-card flat bordered class="detail-card q-mb-md">
        <q-tabs
          v-model="activeTab"
          dense
          no-caps
          inline-label
          active-color="primary"
          indicator-color="primary"
          align="left"
          class="detail-tabs"
        >
          <q-tab v-if="isHumanAssigned" name="comments" icon="chat_bubble_outline">
            <span class="q-ml-xs tab-label">{{ $t('comments_and_runs') }}</span>
            <q-badge v-if="visibleComments.length + runs.length > 0" color="primary" text-color="white" class="tab-count-badge">
              {{ visibleComments.length + runs.length }}
            </q-badge>
          </q-tab>
          <q-tab name="runs" icon="smart_toy" v-if="!isHumanAssigned">
            <span class="q-ml-xs tab-label">{{ $t('docnet_runs') }}</span>
            <q-badge v-if="runs.length > 0" color="primary" text-color="white" class="tab-count-badge">
              {{ runs.length }}
            </q-badge>
          </q-tab>
          <q-tab name="activity" icon="history">
            <span class="q-ml-xs tab-label">{{ $t('docnet_activity') }}</span>
            <q-badge v-if="issue.activity.length > 0" color="primary" text-color="white" class="tab-count-badge">
              {{ issue.activity.length }}
            </q-badge>
          </q-tab>
        </q-tabs>

        <q-separator />

        <q-tab-panels v-model="activeTab" animated class="detail-tab-panels">
          <!-- Comments tab (human-assigned only) -->
          <q-tab-panel v-if="isHumanAssigned" name="comments" class="q-pa-md">
            <CommentThread :comments="visibleComments" :runs="runs" :human-assigned="!isResolved" :read-only="isResolved" @add-comment="onAddComment" @stop-run="onStopRun" />
          </q-tab-panel>

          <!-- Runs tab (agent-assigned only) -->
          <q-tab-panel v-if="!isHumanAssigned" name="runs" class="q-pa-md">
            <CommentThread :comments="visibleComments" :runs="runs" :read-only="true" @stop-run="onStopRun" />
          </q-tab-panel>

          <!-- Activity tab -->
          <q-tab-panel name="activity" class="q-pa-md">
            <div v-if="recentActivity.length > 0" class="activity-log">
              <div v-for="entry in recentActivity" :key="entry.id" class="activity-entry">
                <q-icon
                  :name="entry.actor_type === 'agent' ? 'smart_toy' : 'person'"
                  size="16px"
                  color="grey-6"
                />
                <div class="activity-entry__body">
                  <span class="activity-entry__text">
                    <strong>{{ entry.actor_name }}</strong> {{ entry.action }}
                  </span>
                  <span v-if="entry.details" class="activity-entry__details">{{ entry.details }}</span>
                  <span class="text-caption text-grey-6">{{ formatRelative(entry.created_on) }}</span>
                </div>
              </div>
            </div>
            <p v-else class="text-grey-6 text-caption q-pa-sm">{{ $t('docnet_no_activity_yet') }}</p>
          </q-tab-panel>
        </q-tab-panels>
      </q-card>

      <!-- Linked Approvals -->
      <q-card v-if="issue.linked_approvals && issue.linked_approvals.length > 0" flat bordered class="detail-card q-mb-md">
        <q-card-section>
          <div class="detail-section-label">{{ $t('docnet_linked_approvals', { n: issue.linked_approvals.length }) }}</div>
          <div v-for="appr in issue.linked_approvals" :key="appr.id" class="approval-row">
            <span class="approval-status-dot" :class="'approval-status-dot--' + appr.status" />
            <span class="approval-status-text">{{ appr.status }}</span>
            <span class="approval-action">{{ appr.action }}</span>
            <span class="approval-ref">{{ appr.reference_id }}</span>
            <q-space />
            <span class="text-caption text-grey-6">{{ formatRelative(appr.created_on) }}</span>
          </div>
        </q-card-section>
      </q-card>

      <!-- Cost Summary -->
      <q-card v-if="issue.cost_summary" flat bordered class="detail-card q-mb-md">
        <q-card-section>
          <div class="detail-section-label">{{ $t('docnet_cost_summary') }}</div>
          <div class="cost-headline">
            <span class="cost-amount">${{ issue.cost_summary.total_cost.toFixed(4) }}</span>
            <span class="cost-tokens text-grey-6">
              {{ $t('docnet_tokens_in_out', { total: formatTokens(issue.cost_summary.tokens_total), in: formatTokens(issue.cost_summary.tokens_in), out: formatTokens(issue.cost_summary.tokens_out) }) }}
            </span>
          </div>
          <div v-if="issue.cost_summary.breakdown && tokenBarSegments.length > 0" class="token-bar-chart q-mt-sm">
            <div class="token-bar">
              <div
                v-for="seg in tokenBarSegments"
                :key="seg.label"
                class="token-bar__segment"
                :style="{ width: seg.percent + '%', backgroundColor: seg.color }"
                :title="seg.label + ': ' + formatTokens(seg.value) + ' tokens'"
              />
            </div>
            <div class="token-bar-legend">
              <span v-for="seg in tokenBarSegments" :key="seg.label" class="token-bar-legend__item">
                <span class="token-bar-legend__dot" :style="{ backgroundColor: seg.color }" />
                {{ seg.label }} {{ formatTokens(seg.value) }}
              </span>
            </div>
          </div>
        </q-card-section>
      </q-card>

      <!-- Email Origin -->
      <q-card v-if="issue.email_origin" flat bordered class="detail-card q-mb-md">
        <q-card-section>
          <div class="detail-section-label">
            <q-icon name="mail" size="14px" class="q-mr-xs" />
            {{ $t('docnet_email_origin') }}
          </div>
          <div class="properties-list">
            <div class="properties-list__item">
              <span class="properties-list__label">{{ $t('docnet_from') }}</span>
              <span>{{ issue.email_origin.sender }}</span>
            </div>
            <div class="properties-list__item">
              <span class="properties-list__label">{{ $t('docnet_email') }}</span>
              <span class="text-caption">{{ issue.email_origin.email }}</span>
            </div>
            <div class="properties-list__item">
              <span class="properties-list__label">{{ $t('docnet_subject') }}</span>
              <span class="text-caption">{{ issue.email_origin.subject }}</span>
            </div>
            <div class="properties-list__item">
              <span class="properties-list__label">{{ $t('docnet_type') }}</span>
              <q-badge :color="emailClassificationColor" size="sm">{{ issue.email_origin.classification }}</q-badge>
            </div>
            <div v-if="issue.email_origin.attachment_count > 0" class="properties-list__item">
              <span class="properties-list__label">{{ $t('docnet_attachments') }}</span>
              <span>{{ issue.email_origin.attachment_count }}</span>
            </div>
          </div>
          <q-btn
            flat
            dense
            color="primary"
            :label="$t('docnet_view_email')"
            icon="open_in_new"
            size="sm"
            no-caps
            class="q-mt-sm"
            @click="router.push('/doc-net/email')"
          />
        </q-card-section>
      </q-card>
    </div>

    <!-- Edit dialog -->
    <IssueForm
      v-model="showEditDialog"
      :task="issue"
      :agents="agentOptions"
      :missions="missionOptions"
      @save="onEditSave"
    />
  </div>
</template>

<script lang="ts">
import { notify } from 'src/components/notifications/notify';
import { defineComponent } from 'vue';
import { useRouter } from 'vue-router';
import { useDocNetIssueStore } from 'src/store/DocNet/docnet-issues.store';
import { useDocNetAgentStore } from 'src/store/DocNet/docnet-agents.store';
import { useDocNetMissionStore } from 'src/store/DocNet/docnet-missions.store';
import { useDocNetWebSocketStore } from 'src/store/DocNet/docnet-websocket.store';
import { DocNetGatewayEventType } from 'src/types/websocket';
import { storeToRefs } from 'pinia';
import { useSettingStore } from 'src/store/main';
import type { DocNetIssueStatus, DocNetIssue } from 'src/@types/docnet';
import { renderMarkdown } from 'src/utils/markdown';
import { formatRelativeTime } from 'src/utils/docnet/formatting';
import StatusBadge from '../shared/StatusBadge.vue';
import PriorityIcon from '../shared/PriorityIcon.vue';
import AssigneeChip from '../shared/AssigneeChip.vue';
import CommentThread from './components/CommentThread.vue';
import IssueForm from './components/IssueForm.vue';
import { priorityLabel } from '../shared/docnet-labels';

interface TokenBarSegment {
  label: string;
  value: number;
  color: string;
  percent: number;
}

export default defineComponent({
  name: 'DocNetIssueDetail',

  components: {
    StatusBadge,
    PriorityIcon,
    AssigneeChip,
    CommentThread,
    IssueForm,
  },

  setup() {
    const router = useRouter();
    const issueStore = useDocNetIssueStore();
    const agentStore = useDocNetAgentStore();
    const missionStore = useDocNetMissionStore();
    const settingStore = useSettingStore();
    const { currentIssue: issue, loading, runs } = storeToRefs(issueStore);
    const { profiles } = storeToRefs(agentStore);
    const { missions } = storeToRefs(missionStore);
    return { router, issueStore, agentStore, missionStore, settingStore, issue, loading, profiles, missions, runs };
  },

  data() {
    return {
      showEditDialog: false,
      activeTab: 'comments',
      editingTitle: false,
      editTitleValue: '',
      editingDescription: false,
      editDescriptionValue: '',
      filteredTagOptions: [] as string[],
      wsUnsubscribe: null as (() => void) | null,
    };
  },

  computed: {
    isHumanAssigned(): boolean {
      return this.issue?.assignee_type === 'human';
    },

    /** Comments to show in the runs / comments tabs.
     *
     *  Filters out ``author_type='system'`` rows.  Those are
     *  re-injection messages written by the HITL re-trigger path
     *  ("The tool 'X' has been APPROVED and EXECUTED...") — the
     *  agent needs them in conversation context for its prompt
     *  rebuild, but a human reading the issue already gets the same
     *  facts (tool ran, with these args, returned this) from the
     *  agent run record above.  Keep the rows in the database;
     *  just don't render them in the human-facing thread. */
    visibleComments(): typeof this.issue.comments {
      const all = this.issue?.comments || [];
      return all.filter(
        (c: { author_type?: string }) => c.author_type !== 'system',
      );
    },

    isResolved(): boolean {
      return ['done', 'cancelled', 'error'].includes(this.issue?.status || '');
    },

    userLocale(): string {
      const amt = this.settingStore.user_settings?.AMOUNTS_LOCALE;
      return amt ? String(amt).replace('_', '-') : undefined;
    },

    issueWallClock(): number {
      if (!this.issue?.created_on || !this.issue?.last_modified_on) return 0;
      const ms = new Date(this.issue.last_modified_on).getTime() - new Date(this.issue.created_on).getTime();
      return ms > 0 ? ms : 0;
    },

    totalTokens(): number {
      return this.runs.reduce((sum, r) => sum + (r.token_usage?.billed ?? 0), 0);
    },

    emailClassificationColor(): string {
      const c = this.issue?.email_origin?.classification || '';
      const map: Record<string, string> = { Invoice: 'blue', POConfirm: 'indigo', Quote: 'teal', Order: 'purple' };
      return map[c] || 'grey';
    },

    recentActivity(): DocNetIssue['activity'] {
      if (!this.issue) return [];
      return [...this.issue.activity]
        .sort((a, b) => new Date(b.created_on).getTime() - new Date(a.created_on).getTime())
        .slice(0, 10);
    },

    statusOptions() {
      const map: Record<string, { labelKey: string; color: string }> = {
        open: { labelKey: 'status_todo', color: '#42a5f5' },
        in_progress: { labelKey: 'status_in_progress', color: '#ffa726' },
        in_review: { labelKey: 'status_in_review', color: '#ab47bc' },
        done: { labelKey: 'status_done', color: '#66bb6a' },
        cancelled: { labelKey: 'status_cancelled', color: '#9e9e9e' },
        error: { labelKey: 'status_error', color: '#ef5350' },
      };
      return Object.entries(map).map(([v, cfg]) => ({
        label: this.$t(cfg.labelKey),
        value: v,
        color: cfg.color,
      }));
    },

    priorityOptions() {
      const map: Record<string, { icon: string; color: string }> = {
        critical: { icon: 'warning', color: '#ef5350' },
        high: { icon: 'keyboard_arrow_up', color: '#ffa726' },
        medium: { icon: 'remove', color: '#ffa726' },
        low: { icon: 'keyboard_arrow_down', color: '#42a5f5' },
      };
      return Object.entries(map).map(([v, cfg]) => ({
        label: priorityLabel(this.$t, v),
        value: v,
        icon: cfg.icon,
        color: cfg.color,
      }));
    },

    availableTags(): string[] {
      const currentTags = new Set(this.issue?.tags || []);
      const allTags = new Set<string>();
      for (const iss of this.issueStore.issues) {
        for (const tag of iss.tags || []) {
          if (!currentTags.has(tag)) allTags.add(tag);
        }
      }
      return [...allTags].sort();
    },

    assigneeOptions() {
      const opts: any[] = [];
      if (this.agentOptions.length) {
        opts.push({ label: this.$t('agents'), value: '__h_agents', header: true, icon: 'smart_toy' });
        for (const a of this.agentOptions) {
          opts.push({ label: a.name, value: a.id, type: 'agent' });
        }
      }
      opts.push({ label: this.$t('docnet_team_members'), value: '__h_humans', header: true, icon: 'group' });
      opts.push(
        { label: 'Amier Haider', value: 'user-001', type: 'human' },
        { label: 'Sarah Mueller', value: 'user-002', type: 'human' },
      );
      return opts;
    },

    agentOptions(): { id: string; name: string; role?: string; workload?: number }[] {
      // Orchestrators and system routers coordinate work but are never
      // assignable themselves — mirror the filter used on the list page.
      return this.profiles
        .filter((p) => p.role !== 'orchestrator' && p.role !== 'router')
        .map((p) => ({
          id: p.agent.id,
          name: p.agent.name,
          role: p.role,
          workload: p.workload_percent,
        }));
    },

    missionOptions(): { id: string; name: string }[] {
      return this.missions.map((m) => ({ id: m.id, name: m.name }));
    },

    tokenBarSegments(): TokenBarSegment[] {
      if (!this.issue?.cost_summary?.breakdown) return [];
      const b = this.issue.cost_summary.breakdown;
      const raw = [
        { label: this.$t('docnet_comments'), value: b.comments_tokens || 0, color: 'var(--q-primary, #1976d2)' },
        { label: this.$t('docnet_activities'), value: b.activities_tokens || 0, color: 'var(--dashboard-accent-yellow, #f59e0b)' },
      ].filter((s) => s.value > 0);
      const total = raw.reduce((sum, s) => sum + s.value, 0);
      if (total === 0) return [];
      return raw.map((s) => ({ ...s, percent: (s.value / total) * 100 }));
    },
  },

  async mounted() {
    const id = this.$route.params.id as string;
    if (id) {
      await Promise.all([
        this.issueStore.fetchIssue(id),
        this.agentStore.fetchProfiles(),
        this.missionStore.fetchMissions(),
        this.issueStore.fetchRuns(id),
      ]);

      // Auto-set in_progress when a human opens their assigned issue
      if (
        this.issue?.assignee_type === 'human' &&
        this.issue?.status === 'todo'
      ) {
        await this.issueStore.updateIssue(id, { status: 'in_progress' as DocNetIssueStatus });
      }

      // Set default tab based on assignee type
      if (this.issue?.assignee_type !== 'human') {
        this.activeTab = 'runs';
      }

      // Subscribe to issue channel for live run events + issue updates
      this.wsUnsubscribe = useDocNetWebSocketStore().onIssueEvent(id, (msg) => {
        if (msg.type === DocNetGatewayEventType.RUN_EVENT && msg.data?.run_id) {
          this.issueStore.pushRunEvent(msg.data.run_id as string, {
            type: (msg.data.event_type || msg.type) as string,
            timestamp: (msg.timestamp || new Date().toISOString()) as string,
            data: (msg.data.data || {}) as Record<string, unknown>,
          });
        } else if (msg.type === DocNetGatewayEventType.RUN_STATUS && msg.data?.run_id) {
          this.issueStore.updateRunStatus(msg.data.run_id as string, msg.data.status as string);
        } else if (msg.type === DocNetGatewayEventType.NEW_RUN && this.issue) {
          this.issueStore.fetchRuns(this.issue.id);
        }
      });
    }
  },

  beforeUnmount() {
    if (this.wsUnsubscribe) {
      this.wsUnsubscribe();
      this.wsUnsubscribe = null;
    }
  },

  methods: {
    renderMarkdown,

    formatDuration(ms: number): string {
      const secs = Math.round(ms / 1000);
      if (secs < 60) return `${secs}s`;
      const mins = Math.floor(secs / 60);
      if (mins < 60) return `${mins}m ${secs % 60}s`;
      const hours = Math.floor(mins / 60);
      return `${hours}h ${mins % 60}m`;
    },

    filterLabels(val: string, update: (cb: () => void) => void): void {
      update(() => {
        const needle = val.toLowerCase();
        this.filteredTagOptions = needle
          ? this.availableTags.filter((t: string) => t.toLowerCase().includes(needle))
          : this.availableTags;
      });
    },

    startEditTitle(): void {
      if (!this.issue) return;
      this.editTitleValue = this.issue.title;
      this.editingTitle = true;
    },

    async saveTitle(): Promise<void> {
      if (!this.issue || !this.editTitleValue.trim()) return;
      await this.issueStore.updateIssue(this.issue.id, { title: this.editTitleValue.trim() });
      this.editingTitle = false;
    },

    cancelEditTitle(): void {
      this.editingTitle = false;
    },

    startEditDescription(): void {
      if (!this.issue) return;
      this.editDescriptionValue = this.issue.description || '';
      this.editingDescription = true;
    },

    async saveDescription(): Promise<void> {
      if (!this.issue) return;
      await this.issueStore.updateIssue(this.issue.id, { description: this.editDescriptionValue });
      this.editingDescription = false;
    },

    cancelEditDescription(): void {
      this.editingDescription = false;
    },

    async onAddComment(payload: { content: string; resolution: 'done' | 'not_done' } | string): Promise<void> {
      if (!this.issue) return;
      // Support both old string format and new object format
      const content = typeof payload === 'string' ? payload : payload.content;
      const resolution = typeof payload === 'string' ? null : payload.resolution;

      // If resolved, mark issue as done BEFORE posting the comment
      // so the orchestrator resume doesn't overwrite the status
      if (resolution === 'done') {
        await this.issueStore.updateIssue(this.issue.id, { status: 'done' as DocNetIssueStatus });
      }

      await this.issueStore.addComment(this.issue.id, content, this.$t('docnet_current_user'));
    },

    async onStatusChange(newStatus: string): Promise<void> {
      if (!this.issue) return;
      await this.issueStore.updateIssue(this.issue.id, { status: newStatus as DocNetIssueStatus });
    },

    async onPriorityChange(val: string): Promise<void> {
      if (!this.issue) return;
      await this.issueStore.updateIssue(this.issue.id, { priority: val });
    },

    async onTagsChange(val: string[]): Promise<void> {
      if (!this.issue) return;
      await this.issueStore.updateIssue(this.issue.id, { tags: val });
    },

    async onAssigneeChange(val: string | null): Promise<void> {
      if (!this.issue) return;
      if (!val) {
        await this.issueStore.updateIssue(this.issue.id, {
          assignee_id: '', assignee_name: '', assignee_type: undefined,
        });
        return;
      }
      const opt = this.assigneeOptions.find((o: any) => o.value === val && !o.header);
      await this.issueStore.updateIssue(this.issue.id, {
        assignee_id: val,
        assignee_name: opt?.label || val,
        assignee_type: opt?.type || 'human',
      });
      // Auto-trigger a run when assigning an agent (only if no run is active)
      if (opt?.type === 'agent' && !this.issueStore.activeRunId) {
        try {
          await this.issueStore.triggerRun(this.issue.id);
          notify.success(this.$t('docnet_agent_run_started_auto'));
        } catch {
          notify.error(this.$t('docnet_agent_run_start_failed'));
        }
      }
    },

    async onStopRun(runId: string): Promise<void> {
      if (!this.issue) return;
      try {
        await this.issueStore.stopRun(this.issue.id, runId);
      } catch {
        notify.error(this.$t('docnet_agent_run_stop_failed'));
      }
    },

    async onEditSave(data: Record<string, unknown>): Promise<void> {
      if (!this.issue) return;
      await this.issueStore.updateIssue(this.issue.id, data as Partial<DocNetIssue>);
      this.showEditDialog = false;
    },

    confirmDelete(): void {
      this.$q.dialog({
        title: this.$t('docnet_delete_issue_title'),
        message: this.$t('docnet_delete_issue_confirm', { name: this.issue?.title }),
        cancel: true,
        persistent: true,
      }).onOk(async () => {
        if (!this.issue) return;
        await this.issueStore.deleteIssue(this.issue.id);
        this.goBack();
      });
    },

    goBack() {
      if (window.history.length > 1) {
        this.router.back();
      } else {
        this.router.push('/doc-net/issues');
      }
    },

    formatDate(isoString: string): string {
      if (!isoString) return '';
      const date = new Date(isoString);
      if (isNaN(date.getTime())) return '';
      return date.toLocaleDateString(undefined, {
        month: 'short',
        day: 'numeric',
        year: 'numeric',
      });
    },

    approvalColor(status: string): string {
      if (status === 'approved') return 'positive';
      if (status === 'rejected') return 'negative';
      return 'warning';
    },

    formatTokens(count: number): string {
      if (count == null) return '0';
      return count.toLocaleString(this.userLocale);
    },

    formatRelative(isoString: string): string {
      const fallback = (d: string) => new Date(d).toLocaleDateString(undefined, {
        month: 'short',
        day: 'numeric',
      });
      return formatRelativeTime(isoString, this.$t, fallback);
    },
  },
});
</script>

